Test.Text:
create procedure CK.sTest as
begin
  insert into S.tTable default values;
  insert into S.tOther default values;
end

Test.Description:
create transformer on CK.sTest as
begin
 insert { set @X = 0; } before all {insert into S.?};
 insert { set @Table = 1; } before single {insert into S.tTable};
 insert { set @k = 9; } after single {insert into S.tOther};
 insert { -- the end... } after single {insert into S.tTable};
end

Test.ResultText:
create procedure CK.sTest as
begin
  set @Table = 1; set @X = 0; insert into S.tTable default values;
  -- the end..
  set @X = 0; insert into S.tOther default values; set @k = 9;
end
